import json

def parse_call(text):
    data = json.loads(text)
    if not isinstance(data, dict) or 'tool' not in data:
        raise ValueError("missing 'tool'")
    args = data.get('args', {})
    if not isinstance(args, dict):
        raise ValueError("'args' must be an object")
    return data['tool'], args

def run_agent(model, tools, task, max_steps=5):
    transcript = ["TASK: " + task]
    for step in range(max_steps):
        out = model(transcript)
        transcript.append(out)
        if out.startswith('FINAL:'):
            return out[len('FINAL:'):].strip()
        try:
            name, args = parse_call(out)
            if name not in tools:
                raise ValueError('unknown tool ' + name)
            result = tools[name](**args)
            transcript.append('OBSERVATION: ' + str(result))
        except Exception as e:
            transcript.append('ERROR: ' + str(e))
    return None

def chain_success(p, n):
    return p ** n

def max_steps(p, target):
    n = 0
    while chain_success(p, n + 1) >= target:
        n += 1
    return n
